head.script:
scwin.onpageload = function() {

};

scwin.openPage = function(srd){
    var tabId = "Test"+String(Math.random()).substring(2);
    var tabOptions = {
            "label": "Test"+String(Math.random()).substring(2), 
            "title": "dataObject",
            "openAction": "new",
            "closable": "true"
        };
    var contentOptions = {   
            "src": srd,
            "frameMode" : "pageFrame",
            "scope" : true, 
            "alwaysDraw": "true"
        };
    wdc_main.addTab(tabId, tabOptions, contentOptions)
        .then(function(_tabId){
            wdc_main.setSelectedTabIndex(wdc_main.getSelectedTabIndex(_tabId));
        });
};

scwin.trigger1_onclick = function(e) {
    scwin.openPage("tC_popup_frModel_scrlErr_WAEA-216_(WSQ-5983)_sub.xml");
};


	scwin.setSimulate1 = function() {
		WebSquare.wUnit.getDomById('wdc_main_container').querySelectorAll('input')[1].scrollIntoView(({behavior:'smooth', block:'start'}));
	}
	scwin.setOffset = function() {
		window.offset = WebSquare.wUnit.getDomById('wdc_main_container').querySelectorAll('input')[1].getBoundingClientRect().top;
	}	
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.checkVal = function() {
		return window.offset == WebSquare.wUnit.getDomById('wdc_main_container').querySelectorAll('input')[1].getBoundingClientRect().top;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_tabhost').querySelectorAll('a')[1].click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "700");		
		WebSquare.wUnit.addCommand("set", "scwin.setOffset()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_container').querySelectorAll('input')[1].click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
